package net.civeira.phylax.feature.observe.observedalertrule.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRule;
import net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject.ThresholdVO;

class ThresholdValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of threshold of observed alert rule")
  void test_threshold_value_holder_assign_plain_value() {
    Object holder = new Object();
    ThresholdValueHolder<Object> value = new ThresholdValueHolder<>(holder);
    Assertions.assertSame(holder, value.threshold(1), "Setters must return the holder");
    Assertions.assertTrue(value.getThresholdValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getThreshold().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of threshold of observed alert rule")
  void test_threshold_value_holder_assign_value_object() {
    Object holder = new Object();
    ThresholdValueHolder<Object> value = new ThresholdValueHolder<>(holder);
    ThresholdVO vo = ThresholdVO.from(1);
    Assertions.assertFalse(value.getThresholdValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.threshold(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getThresholdValue().orElseThrow());
    Assertions.assertSame(holder, value.threshold(Optional.empty()));
    Assertions.assertFalse(value.getThresholdValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.threshold(Optional.of(vo)));
    Assertions.assertSame(vo, value.getThresholdValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of threshold of observed alert rule against the original")
  void test_threshold_value_holder_read() {
    Object holder = new Object();
    ThresholdValueHolder<Object> value = new ThresholdValueHolder<>(holder);
    ThresholdVO vo = ThresholdVO.from(1);
    ThresholdVO other = ThresholdVO.from(1);
    ObservedAlertRule original = Mockito.mock(ObservedAlertRule.class);
    Mockito.when(original.getThresholdValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readThreshold(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readThreshold(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.threshold(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readThreshold(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readThreshold(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of threshold of observed alert rule")
  void test_threshold_value_holder_unset() {
    Object holder = new Object();
    ThresholdValueHolder<Object> value = new ThresholdValueHolder<>(holder);
    ThresholdVO vo = ThresholdVO.from(1);
    value.threshold(vo);
    Assertions.assertSame(holder, value.unsetThresholdIfMatches("threshold_other"));
    Assertions.assertTrue(value.getThresholdValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetThresholdIfMatches("threshold"));
    Assertions.assertFalse(value.getThresholdValue().isPresent(),
        "The field name must clear the value");
    value.threshold(vo);
    Assertions.assertSame(holder, value.unsetThreshold());
    Assertions.assertFalse(value.getThresholdValue().isPresent(), "Unset must clear the value");
  }
}
